// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime, address user) public {
        vm.assume(user != address(0) && user != address(this));
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 + amount2 >= amount1);
        vm.assume(unlockTime > block.timestamp);
        vm.deal(user, amount1 + amount2);

        vm.startPrank(user);
        c.Put{value: amount1}(unlockTime);
        c.Put{value: amount2}(unlockTime);
        vm.stopPrank();

        // After two Puts, the balance should be at least amount1+amount2 (reference) or exactly amount2 (bug).
        // The invariant: balance >= amount1+amount2 ensures previous contributions are not lost.
        uint256 balance = c.Acc(user);
        assertTrue(balance >= amount1 + amount2);
    }
}

