        c.Put{value: amt2}(unlockTime);

        // No collects have occurred; invariant: sum of Acc balances equals contract balance minus initial
        uint256 sumBalances = c.Acc(user1).balance + c.Acc(user2).balance;
        uint256 expected = address(c).balance - initialBal;
        assertTrue(sumBalances == expected);
