pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 preBalance, uint256 msgValue, uint256 unlockTime) public {
        vm.assume(msgValue > 0);
        address user = address(0x1234);
        vm.deal(user, msgValue);
        // Set up pre-existing balance in contract state.
        // We cannot directly set storage, so we use a pranked Put with 0 value to deployer? No.
        // Instead, we first call Put with a tiny value to create entry, then manually set via internal? No vm.store.
        // We use a workaround: preBalance is the balance before the fuzzed Put.
        // We need to set Acc[user].balance = preBalance without vm.store.
        // We can use the fact that Put accumulates; we can call Put many times? Too complex.
        // Since the bug is overflow in balance += msg.value, we need to control the initial balance.
        // We can deploy a helper that calls Put with value and then we set? No.
        // Instead, we can use the fact that the invariant is: if preBalance + msgValue > preBalance (no overflow),
        // then postBalance > preBalance strictly. The bug violates this if overflow occurs.
        // We cannot easily set an arbitrary preBalance without vm.store, which is forbidden.
        // Thus we restrict: we only test that if no overflow, balance strictly increases.
        // The bug allows any msgValue to cause overflow if preBalance is large.
        // We need to get preBalance from contract's state after some initial Put.
        // Simplest: first, do a normal Put to set some balance, then get that as preBalance via getter.
        vm.prank(user);
        c.Put{value: preBalance}(unlockTime);
        uint256 beforeBalance = c.Acc(user).balance;
        // Now do the fuzzed Put with msgValue.
        vm.deal(user, msgValue);
        vm.prank(user);
        c.Put{value: msgValue}(unlockTime);
        uint256 afterBalance = c.Acc(user).balance;
        // Invariant: if the addition did not overflow, afterBalance must be greater than beforeBalance.
        // If overflow occurred, afterBalance could be <= beforeBalance.
        // The rule: afterBalance > beforeBalance.
        // This rule holds for reference because of the require check preventing overflow.
        // Buggy version lacks the require, so overflow possible, breaking the rule.
        // But we need the rule to hold for ALL admissible inputs in reference.
        // In reference, overflow is impossible due to require, so afterBalance > beforeBalance always.
        // In buggy, overflow possible, so afterBalance > beforeBalance can be false.
        assertTrue(afterBalance > beforeBalance);
    }
}

