pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 preBalance, uint256 putValue, uint256 collectValue, uint256 unlockTime) public {
        // Keep values in admissible domain; preBalance can be large to enable overflow setup
        vm.assume(unlockTime > block.timestamp + 1 days);
        vm.assume(preBalance <= type(uint256).max);
        vm.assume(putValue <= type(uint256).max);
        vm.assume(collectValue <= type(uint256).max);
        address actor = address(0xdead);

        // Set up preBalance by pranking an initial Put with correct msg.value
        vm.deal(actor, preBalance + putValue + collectValue + 1 ether);
        vm.prank(actor);
        c.Put{value: preBalance}(unlockTime);

        // Warp past unlock time so collect is possible
        vm.warp(unlockTime + 1);

        // Record pre-collect balance
        uint256 balanceBeforeCollect = c.Acc(actor).balance;

        // Now make a second Put with a msg.value that does NOT overflow when added to preBalance
        bool noOverflow = (preBalance <= type(uint256).max - putValue);
        vm.assume(noOverflow);
        vm.prank(actor);
        c.Put{value: putValue}(unlockTime + 2 days);

        // Record post-Put balance
        uint256 balanceAfterPut = c.Acc(actor).balance;

        // Assert: post-balance equals pre-balance plus putValue
        assertTrue(balanceAfterPut == preBalance + putValue);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint _unlockTime, uint _deposit, uint _collect) public payable {
        require(_deposit > 0 && _collect > 0 && _collect <= _deposit);
        require(_unlockTime < block.timestamp);
        require(address(this).balance >= _deposit);

        uint balBefore = address(c).balance;
        c.Put{value: _deposit}(_unlockTime);

        uint balAfterDeposit = address(c).balance;
        require(balAfterDeposit == balBefore + _deposit);

        c.Collect(_collect);

        uint balAfterCollect = address(c).balance;
        assert(balAfterCollect == balAfterDeposit - _collect);
    }
}

