contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        // Restrict to amounts that fit within reasonable bounds to avoid overflow in setup
        depositAmount = bound(depositAmount, 1, type(uint256).max / 2);
        collectAmount = bound(collectAmount, 1, type(uint256).max / 2);

        // Ensure the account has a nonzero balance by depositing via Put
        address actor = address(0x1234);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Put{value: depositAmount}(block.timestamp + 1);

        // Attempt to collect an amount; observe whether it reverts
        bool collected;
        vm.prank(actor);
        try c.Collect(collectAmount) {
            collected = true;
        } catch {
            collected = false;
        }

        // General rule: if collectAmount > depositAmount, Collect must revert.
        // The correct contract reverts on underflow; the mutant subtracts under any condition,
        // leading to a revert on underflow but the assertion below encodes the intended rule:
        // Collect should not revert when collectAmount <= depositAmount, but the mutant may still succeed due to underflow wrapping?
        // Actually the correct C reverts if acc.balance < _am OR if block.timestamp <= unlockTime OR if acc.balance < MinSum.
        // The mutant always executes acc.balance -= _am, which will revert on underflow if _am > balance.
        // So the correct C reverts when _am > balance; the mutant also reverts (due to underflow).
        // We need a property that holds for all inputs on C but fails on M.
        // Instead, consider: after a successful Collect, the contract ETH balance must not increase.
        // Because the mutant always proceeds, it may succeed when C would fail, leading to a successful collect and ETH transfer.
        // For C, Collect succeeds only if depositAmount >= MinSum (1 ether) and depositAmount >= collectAmount and timestamp > unlockTime.
        // If we ensure depositAmount < 1 ether, C will never succeed, but M will succeed if collectAmount <= depositAmount.
        // Therefore, assume depositAmount < 1 ether. Then C always reverts; M succeeds for collectAmount <= depositAmount.
        // Rule: If depositAmount < 1 ether, Collect must always revert.
        vm.assume(depositAmount < 1 ether);

        // After the attempt, assert that collected is false for the correct contract.
        // For M, collected can be true when collectAmount <= depositAmount, violating the rule.
        assertTrue(!collected);
    }
